//! Parity against three.js.
//!
//! Loads every fixture in `parity/math/` (generated by `parity/math/gen/generate.mjs` from
//! the real three.js `src/math` modules), runs the same operation on the Rust port
//! and requires `|got - expected| <= 1e-6 * max(1, |expected|)` (DECISIONS.md D2).
//! Non-finite values must match exactly. An op the dispatcher does not know fails the test.
//!
//! Run with `cargo test --test parity -- --nocapture` to see the per-type error summary.

use serde_json::Value;
use std::collections::BTreeSet;
use wamr_math::color_management::{self, ColorSpace};
use wamr_math::math_utils::{self, ComponentType, ProperEulerOrder};
use wamr_math::*;

#[path = "parity/io.rs"]
mod io;
#[path = "parity/shapes.rs"]
mod shapes;
use io::{In, Out, COMPONENT_TYPES, PROPER_ORDERS};
use shapes::run_shapes;

const TOLERANCE: f64 = 1e-6;

fn fixture_dir() -> String {
    std::env::var("WAMR_PARITY_DIR").unwrap_or_else(|_| concat!(env!("CARGO_MANIFEST_DIR"), "/../../parity/math").to_string())
}

fn load(name: &str) -> Value {
    let path = format!("{}/{name}.json", fixture_dir());
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("cannot read {path}: {e}"));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("cannot parse {path}: {e}"))
}

fn number(v: &Value) -> f64 {
    match v {
        Value::Number(n) => n.as_f64().unwrap(),
        Value::String(s) => match s.as_str() {
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            "NaN" => f64::NAN,
            other => panic!("unexpected string in number array: {other}"),
        },
        other => panic!("unexpected value in number array: {other}"),
    }
}

fn numbers(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(number).collect()
}


macro_rules! vector_common {
    ($name:ident, $T:ty, $rd:ident, $wr:ident) => {
        fn $name(method: &str, r: &mut In, o: &mut Out) -> bool {
            match method {
                "setScalar" => { let mut v = r.$rd(); o.$wr(v.set_scalar(r.s())) }
                "setComponent" => { let mut v = r.$rd(); let i = r.u(); o.$wr(v.set_component(i, r.s())) }
                "getComponent" => { let v = r.$rd(); o.s(v.get_component(r.u())) }
                "add" => { let mut v = r.$rd(); o.$wr(v.add(&r.$rd())) }
                "addScalar" => { let mut v = r.$rd(); o.$wr(v.add_scalar(r.s())) }
                "addVectors" => { let (a, b) = (r.$rd(), r.$rd()); o.$wr(<$T>::default().add_vectors(&a, &b)) }
                "addScaledVector" => { let mut v = r.$rd(); let a = r.$rd(); o.$wr(v.add_scaled_vector(&a, r.s())) }
                "sub" => { let mut v = r.$rd(); o.$wr(v.sub(&r.$rd())) }
                "subScalar" => { let mut v = r.$rd(); o.$wr(v.sub_scalar(r.s())) }
                "subVectors" => { let (a, b) = (r.$rd(), r.$rd()); o.$wr(<$T>::default().sub_vectors(&a, &b)) }
                "multiply" => { let mut v = r.$rd(); o.$wr(v.multiply(&r.$rd())) }
                "multiplyScalar" => { let mut v = r.$rd(); o.$wr(v.multiply_scalar(r.s())) }
                "divide" => { let mut v = r.$rd(); o.$wr(v.divide(&r.$rd())) }
                "divideScalar" => { let mut v = r.$rd(); o.$wr(v.divide_scalar(r.s())) }
                "min" => { let mut v = r.$rd(); o.$wr(v.min(&r.$rd())) }
                "max" => { let mut v = r.$rd(); o.$wr(v.max(&r.$rd())) }
                "clamp" => { let mut v = r.$rd(); let (a, b) = (r.$rd(), r.$rd()); o.$wr(v.clamp(&a, &b)) }
                "clampScalar" => { let mut v = r.$rd(); let (a, b) = (r.s(), r.s()); o.$wr(v.clamp_scalar(a, b)) }
                "clampLength" => { let mut v = r.$rd(); let (a, b) = (r.s(), r.s()); o.$wr(v.clamp_length(a, b)) }
                "floor" => o.$wr(r.$rd().floor()),
                "ceil" => o.$wr(r.$rd().ceil()),
                "round" => o.$wr(r.$rd().round()),
                "roundToZero" => o.$wr(r.$rd().round_to_zero()),
                "negate" => o.$wr(r.$rd().negate()),
                "dot" => { let v = r.$rd(); o.s(v.dot(&r.$rd())) }
                "lengthSq" => o.s(r.$rd().length_sq()),
                "length" => o.s(r.$rd().length()),
                "manhattanLength" => o.s(r.$rd().manhattan_length()),
                "normalize" => o.$wr(r.$rd().normalize()),
                "setLength" => { let mut v = r.$rd(); o.$wr(v.set_length(r.s())) }
                "lerp" => { let mut v = r.$rd(); let a = r.$rd(); o.$wr(v.lerp(&a, r.s())) }
                "lerpVectors" => { let (a, b) = (r.$rd(), r.$rd()); o.$wr(<$T>::default().lerp_vectors(&a, &b, r.s())) }
                "equals" => { let v = r.$rd(); o.b(v.equals(&r.$rd())) }
                _ => return false,
            }
            true
        }
    };
}

vector_common!(vector2_common, Vector2, v2, v2);
vector_common!(vector3_common, Vector3, v3, v3);
vector_common!(vector4_common, Vector4, v4, v4);

#[rustfmt::skip]
fn run(op: &str, r: &mut In, o: &mut Out) -> bool {
    let (ty, method) = op.split_once('.').unwrap();

    match ty {
        "Vector2" if vector2_common(method, r, o) => return true,
        "Vector3" if vector3_common(method, r, o) => return true,
        "Vector4" if vector4_common(method, r, o) => return true,
        _ => {}
    }

    match op {
        // ---- MathUtils
        "MathUtils.clamp" => { let (a, b, c) = (r.s(), r.s(), r.s()); o.s(math_utils::clamp(a, b, c)) }
        "MathUtils.euclideanModulo" => { let (a, b) = (r.s(), r.s()); o.s(math_utils::euclidean_modulo(a, b)) }
        "MathUtils.mapLinear" => { let (x, a1, d, b1, b2) = (r.s(), r.s(), r.s(), r.s(), r.s()); o.s(math_utils::map_linear(x, a1, a1 + d, b1, b2)) }
        "MathUtils.inverseLerp" => { let (a, b, c) = (r.s(), r.s(), r.s()); o.s(math_utils::inverse_lerp(a, b, c)) }
        "MathUtils.lerp" => { let (a, b, c) = (r.s(), r.s(), r.s()); o.s(math_utils::lerp(a, b, c)) }
        "MathUtils.damp" => { let (a, b, c, d) = (r.s(), r.s(), r.s(), r.s()); o.s(math_utils::damp(a, b, c, d)) }
        "MathUtils.pingpong" => { let (a, b) = (r.s(), r.s()); o.s(math_utils::pingpong(a, b)) }
        "MathUtils.smoothstep" => { let (a, b, c) = (r.s(), r.s(), r.s()); o.s(math_utils::smoothstep(a, b, c)) }
        "MathUtils.smootherstep" => { let (a, b, c) = (r.s(), r.s(), r.s()); o.s(math_utils::smootherstep(a, b, c)) }
        "MathUtils.seededRandom" => {
            o.d(math_utils::seeded_random(Some(r.d() as u32)));
            for _ in 0..3 { o.d(math_utils::seeded_random(None)); }
        }
        "MathUtils.degToRad" => o.s(math_utils::deg_to_rad(r.s())),
        "MathUtils.radToDeg" => o.s(math_utils::rad_to_deg(r.s())),
        "MathUtils.isPowerOfTwo" => o.b(math_utils::is_power_of_two(r.s())),
        "MathUtils.ceilPowerOfTwo" => o.s(math_utils::ceil_power_of_two(r.s())),
        "MathUtils.floorPowerOfTwo" => o.s(math_utils::floor_power_of_two(r.s())),
        "MathUtils.setQuaternionFromProperEuler" => {
            let (a, b, c) = (r.s(), r.s(), r.s());
            let mut q = Quaternion::default();
            math_utils::set_quaternion_from_proper_euler(&mut q, a, b, c, PROPER_ORDERS[r.u()]);
            o.q(&q)
        }
        "MathUtils.normalize" => { let v = r.s(); o.s(math_utils::normalize(v, COMPONENT_TYPES[r.u()])) }
        "MathUtils.denormalize" => { let v = r.s(); o.s(math_utils::denormalize(v, COMPONENT_TYPES[r.u()])) }

        // ---- Vector2
        "Vector2.angleTo" => { let v = r.v2(); o.s(v.angle_to(&r.v2())) }
        "Vector2.distanceTo" => { let v = r.v2(); o.s(v.distance_to(&r.v2())) }
        "Vector2.distanceToSquared" => { let v = r.v2(); o.s(v.distance_to_squared(&r.v2())) }
        "Vector2.manhattanDistanceTo" => { let v = r.v2(); o.s(v.manhattan_distance_to(&r.v2())) }
        "Vector2.applyMatrix3" => { let mut v = r.v2(); o.v2(v.apply_matrix3(&r.m3())) }
        "Vector2.cross" => { let v = r.v2(); o.s(v.cross(&r.v2())) }
        "Vector2.angle" => o.s(r.v2().angle()),
        "Vector2.rotateAround" => { let mut v = r.v2(); let c = r.v2(); o.v2(v.rotate_around(&c, r.s())) }

        // ---- Vector3
        "Vector3.angleTo" => { let v = r.v3(); o.s(v.angle_to(&r.v3())) }
        "Vector3.distanceTo" => { let v = r.v3(); o.s(v.distance_to(&r.v3())) }
        "Vector3.distanceToSquared" => { let v = r.v3(); o.s(v.distance_to_squared(&r.v3())) }
        "Vector3.manhattanDistanceTo" => { let v = r.v3(); o.s(v.manhattan_distance_to(&r.v3())) }
        "Vector3.multiplyVectors" => { let (a, b) = (r.v3(), r.v3()); o.v3(Vector3::default().multiply_vectors(&a, &b)) }
        "Vector3.applyEuler" => { let mut v = r.v3(); o.v3(v.apply_euler(&r.e())) }
        "Vector3.applyAxisAngle" => { let mut v = r.v3(); let a = r.v3(); o.v3(v.apply_axis_angle(&a, r.s())) }
        "Vector3.applyMatrix3" => { let mut v = r.v3(); o.v3(v.apply_matrix3(&r.m3())) }
        "Vector3.applyNormalMatrix" => { let mut v = r.v3(); o.v3(v.apply_normal_matrix(&r.m3())) }
        "Vector3.applyMatrix4" | "Vector3.applyMatrix4.trs" | "Vector3.applyMatrix4.proj" => { let mut v = r.v3(); o.v3(v.apply_matrix4(&r.m4())) }
        "Vector3.applyQuaternion" => { let mut v = r.v3(); o.v3(v.apply_quaternion(&r.q())) }
        "Vector3.transformDirection" => { let mut v = r.v3(); o.v3(v.transform_direction(&r.m4())) }
        "Vector3.cross" => { let mut v = r.v3(); o.v3(v.cross(&r.v3())) }
        "Vector3.crossVectors" => { let (a, b) = (r.v3(), r.v3()); o.v3(Vector3::default().cross_vectors(&a, &b)) }
        "Vector3.projectOnVector" => { let mut v = r.v3(); o.v3(v.project_on_vector(&r.v3())) }
        "Vector3.projectOnPlane" => { let mut v = r.v3(); o.v3(v.project_on_plane(&r.v3())) }
        "Vector3.reflect" => { let mut v = r.v3(); o.v3(v.reflect(&r.v3())) }
        "Vector3.setFromSpherical" => o.v3(Vector3::default().set_from_spherical(&r.sphl())),
        "Vector3.setFromSphericalCoords" => { let (a, b, c) = (r.s(), r.s(), r.s()); o.v3(Vector3::default().set_from_spherical_coords(a, b, c)) }
        "Vector3.setFromCylindrical" => o.v3(Vector3::default().set_from_cylindrical(&r.cyl())),
        "Vector3.setFromCylindricalCoords" => { let (a, b, c) = (r.s(), r.s(), r.s()); o.v3(Vector3::default().set_from_cylindrical_coords(a, b, c)) }
        "Vector3.setFromMatrixPosition" => o.v3(Vector3::default().set_from_matrix_position(&r.m4())),
        "Vector3.setFromMatrixScale" => o.v3(Vector3::default().set_from_matrix_scale(&r.m4())),
        "Vector3.setFromMatrixColumn" => { let m = r.m4(); o.v3(Vector3::default().set_from_matrix_column(&m, r.u())) }
        "Vector3.setFromMatrix3Column" => { let m = r.m3(); o.v3(Vector3::default().set_from_matrix3_column(&m, r.u())) }
        "Vector3.setFromEuler" => o.v3(Vector3::default().set_from_euler(&r.e())),
        "Vector3.setFromColor" => o.v3(Vector3::default().set_from_color(&r.c())),

        // ---- Vector4
        "Vector4.applyMatrix4" => { let mut v = r.v4(); o.v4(v.apply_matrix4(&r.m4())) }
        "Vector4.setAxisAngleFromQuaternion" => o.v4(Vector4::default().set_axis_angle_from_quaternion(&r.q())),
        "Vector4.setAxisAngleFromRotationMatrix" => o.v4(Vector4::default().set_axis_angle_from_rotation_matrix(&r.m4())),
        "Vector4.setFromMatrixPosition" => o.v4(Vector4::default().set_from_matrix_position(&r.m4())),

        // ---- Matrix3
        "Matrix3.set" => { let e = r.m3().elements; o.m3(Matrix3::default().set(e[0], e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8])) }
        "Matrix3.extractBasis" => {
            let (mut x, mut y, mut z) = (Vector3::default(), Vector3::default(), Vector3::default());
            r.m3().extract_basis(&mut x, &mut y, &mut z);
            o.v3(&x); o.v3(&y); o.v3(&z)
        }
        "Matrix3.setFromMatrix4" => o.m3(Matrix3::default().set_from_matrix4(&r.m4())),
        "Matrix3.multiply" => { let mut a = r.m3(); o.m3(a.multiply(&r.m3())) }
        "Matrix3.premultiply" => { let mut a = r.m3(); o.m3(a.premultiply(&r.m3())) }
        "Matrix3.multiplyMatrices" => { let (a, b) = (r.m3(), r.m3()); o.m3(Matrix3::default().multiply_matrices(&a, &b)) }
        "Matrix3.multiplyScalar" => { let mut m = r.m3(); o.m3(m.multiply_scalar(r.s())) }
        "Matrix3.determinant" => o.s(r.m3().determinant()),
        "Matrix3.invert" => o.m3(r.m3().invert()),
        "Matrix3.transpose" => o.m3(r.m3().transpose()),
        "Matrix3.getNormalMatrix" | "Matrix3.getNormalMatrix.trs" => o.m3(Matrix3::default().get_normal_matrix(&r.m4())),
        "Matrix3.transposeIntoArray" => { let mut a = [0.0; 9]; r.m3().transpose_into_array(&mut a); o.a(&a) }
        "Matrix3.setUvTransform" => {
            let (tx, ty, sx, sy, rot, cx, cy) = (r.s(), r.s(), r.s(), r.s(), r.s(), r.s(), r.s());
            o.m3(Matrix3::default().set_uv_transform(tx, ty, sx, sy, rot, cx, cy))
        }
        "Matrix3.makeTranslation" => { let (x, y) = (r.s(), r.s()); o.m3(Matrix3::default().make_translation(x, y)) }
        "Matrix3.makeRotation" => o.m3(Matrix3::default().make_rotation(r.s())),
        "Matrix3.makeScale" => { let (x, y) = (r.s(), r.s()); o.m3(Matrix3::default().make_scale(x, y)) }
        "Matrix3.equals" => { let a = r.m3(); o.b(a.equals(&r.m3())) }

        // ---- Matrix4
        "Matrix4.set" => {
            let e = r.m4().elements;
            o.m4(Matrix4::default().set(e[0], e[1], e[2], e[3], e[4], e[5], e[6], e[7], e[8], e[9], e[10], e[11], e[12], e[13], e[14], e[15]))
        }
        "Matrix4.copyPosition" => { let mut a = r.m4(); o.m4(a.copy_position(&r.m4())) }
        "Matrix4.setFromMatrix3" => o.m4(Matrix4::default().set_from_matrix3(&r.m3())),
        "Matrix4.extractBasis" => {
            let nine = Vector3::new(9.0, 9.0, 9.0);
            let (mut x, mut y, mut z) = (nine, nine, nine);
            r.m4().extract_basis(&mut x, &mut y, &mut z);
            o.v3(&x); o.v3(&y); o.v3(&z)
        }
        "Matrix4.makeBasis" => { let (x, y, z) = (r.v3(), r.v3(), r.v3()); o.m4(Matrix4::default().make_basis(&x, &y, &z)) }
        "Matrix4.extractRotation" => { let mut base = r.m4(); o.m4(base.extract_rotation(&r.m4())) }
        "Matrix4.makeRotationFromEuler" => o.m4(Matrix4::default().make_rotation_from_euler(&r.e())),
        "Matrix4.makeRotationFromQuaternion" => o.m4(Matrix4::default().make_rotation_from_quaternion(&r.q())),
        "Matrix4.lookAt" => { let mut m = r.m4(); let (eye, target, up) = (r.v3(), r.v3(), r.v3()); o.m4(m.look_at(&eye, &target, &up)) }
        "Matrix4.multiply" => { let mut a = r.m4(); o.m4(a.multiply(&r.m4())) }
        "Matrix4.premultiply" => { let mut a = r.m4(); o.m4(a.premultiply(&r.m4())) }
        "Matrix4.multiplyMatrices" | "Matrix4.multiplyMatrices.trs" => { let (a, b) = (r.m4(), r.m4()); o.m4(Matrix4::default().multiply_matrices(&a, &b)) }
        "Matrix4.multiplyScalar" => { let mut m = r.m4(); o.m4(m.multiply_scalar(r.s())) }
        "Matrix4.determinant" => o.s(r.m4().determinant()),
        "Matrix4.determinantAffine" => o.s(r.m4().determinant_affine()),
        "Matrix4.transpose" => o.m4(r.m4().transpose()),
        "Matrix4.setPosition" => { let mut m = r.m4(); let (x, y, z) = (r.s(), r.s(), r.s()); o.m4(m.set_position(x, y, z)) }
        "Matrix4.invert" | "Matrix4.invert.trs" | "Matrix4.invert.proj" => o.m4(r.m4().invert()),
        "Matrix4.scale" => { let mut m = r.m4(); o.m4(m.scale(&r.v3())) }
        "Matrix4.getMaxScaleOnAxis" => o.s(r.m4().get_max_scale_on_axis()),
        "Matrix4.makeTranslation" => { let (x, y, z) = (r.s(), r.s(), r.s()); o.m4(Matrix4::default().make_translation(x, y, z)) }
        "Matrix4.makeRotationX" => o.m4(Matrix4::default().make_rotation_x(r.s())),
        "Matrix4.makeRotationY" => o.m4(Matrix4::default().make_rotation_y(r.s())),
        "Matrix4.makeRotationZ" => o.m4(Matrix4::default().make_rotation_z(r.s())),
        "Matrix4.makeRotationAxis" => { let v = r.v3(); o.m4(Matrix4::default().make_rotation_axis(&v, r.s())) }
        "Matrix4.makeScale" => { let (x, y, z) = (r.s(), r.s(), r.s()); o.m4(Matrix4::default().make_scale(x, y, z)) }
        "Matrix4.makeShear" => {
            let (a, b, c, d, e, f) = (r.s(), r.s(), r.s(), r.s(), r.s(), r.s());
            o.m4(Matrix4::default().make_shear(a, b, c, d, e, f))
        }
        "Matrix4.compose" => { let (p, q, s) = (r.v3(), r.q(), r.v3()); o.m4(Matrix4::default().compose(&p, &q, &s)) }
        "Matrix4.decompose" | "Matrix4.decompose.trs" => {
            let nine = Vector3::new(9.0, 9.0, 9.0);
            let (mut p, mut q, mut s) = (nine, Quaternion::new(9.0, 9.0, 9.0, 9.0), nine);
            r.m4().decompose(&mut p, &mut q, &mut s);
            o.v3(&p); o.q(&q); o.v3(&s)
        }
        "Matrix4.makePerspective" | "Matrix4.makeOrthographic" => {
            // the generator builds right = left + width, top = bottom + height, far = near + depth
            let (l, w, b, h, n, d) = (r.s(), r.s(), r.s(), r.s(), r.s(), r.s());
            let (cs, rev) = (r.cs(), r.b());
            let mut m = Matrix4::default();
            if op == "Matrix4.makePerspective" {
                m.make_perspective(l, l + w, b + h, b, n, n + d, cs, rev);
            } else {
                m.make_orthographic(l, l + w, b + h, b, n, n + d, cs, rev);
            }
            o.m4(&m)
        }
        "Matrix4.equals" => { let a = r.m4(); o.b(a.equals(&r.m4())) }

        // ---- Quaternion
        "Quaternion.slerpFlat" => {
            let (a, b) = (r.q().to_array(), r.q().to_array());
            let mut dst = [0.0; 4];
            Quaternion::slerp_flat(&mut dst, 0, &a, 0, &b, 0, r.s());
            o.a(&dst)
        }
        "Quaternion.multiplyQuaternionsFlat" => {
            let (a, b) = (r.q().to_array(), r.q().to_array());
            let mut dst = [0.0; 4];
            Quaternion::multiply_quaternions_flat(&mut dst, 0, &a, 0, &b, 0);
            o.a(&dst)
        }
        "Quaternion.setFromEuler" => o.q(Quaternion::default().set_from_euler(&r.e())),
        "Quaternion.setFromAxisAngle" => { let v = r.v3(); o.q(Quaternion::default().set_from_axis_angle(&v, r.s())) }
        "Quaternion.setFromRotationMatrix" => o.q(Quaternion::default().set_from_rotation_matrix(&r.m4())),
        "Quaternion.setFromUnitVectors" => { let (a, b) = (r.v3(), r.v3()); o.q(Quaternion::default().set_from_unit_vectors(&a, &b)) }
        "Quaternion.setFromUnitVectors.opposite" => {
            let a = r.v3();
            let mut b = a;
            b.negate();
            o.q(Quaternion::default().set_from_unit_vectors(&a, &b))
        }
        "Quaternion.angleTo" => { let a = r.q(); o.s(a.angle_to(&r.q())) }
        "Quaternion.rotateTowards" => { let mut a = r.q(); let b = r.q(); o.q(a.rotate_towards(&b, r.s())) }
        "Quaternion.invert" => o.q(r.q().invert()),
        "Quaternion.conjugate" => o.q(r.q().conjugate()),
        "Quaternion.dot" => { let a = r.q(); o.s(a.dot(&r.q())) }
        "Quaternion.lengthSq" => o.s(r.q().length_sq()),
        "Quaternion.length" => o.s(r.q().length()),
        "Quaternion.normalize" => o.q(r.q().normalize()),
        "Quaternion.multiply" => { let mut a = r.q(); o.q(a.multiply(&r.q())) }
        "Quaternion.premultiply" => { let mut a = r.q(); o.q(a.premultiply(&r.q())) }
        "Quaternion.multiplyQuaternions" => { let (a, b) = (r.q(), r.q()); o.q(Quaternion::default().multiply_quaternions(&a, &b)) }
        "Quaternion.slerp" | "Quaternion.slerp.any" => { let mut a = r.q(); let b = r.q(); o.q(a.slerp(&b, r.s())) }
        "Quaternion.slerpQuaternions" => { let (a, b) = (r.q(), r.q()); o.q(Quaternion::default().slerp_quaternions(&a, &b, r.s())) }
        "Quaternion.equals" => { let a = r.q(); o.b(a.equals(&r.q())) }

        // ---- Euler
        "Euler.setFromRotationMatrix" => { let m = r.m4(); o.e(Euler::default().set_from_rotation_matrix(&m, r.ord())) }
        "Euler.setFromQuaternion" | "Euler.setFromQuaternion.any" => { let q = r.q(); o.e(Euler::default().set_from_quaternion(&q, r.ord())) }
        "Euler.setFromVector3" => { let v = r.v3(); o.e(Euler::default().set_from_vector3(&v, r.ord())) }
        "Euler.reorder" => { let mut e = r.e(); o.e(e.reorder(r.ord())) }
        "Euler.equals" => { let a = r.e(); o.b(a.equals(&r.e())) }

        // ---- Color
        "Color.setScalar" => o.c(Color::default().set_scalar(r.s())),
        "Color.setHex" => { let hex = r.u() as u32; o.c(Color::default().set_hex(hex, r.cspace())) }
        "Color.setRGB" => { let c = r.c(); o.c(Color::default().set_rgb(c.r, c.g, c.b, r.cspace())) }
        "Color.setHSL" | "Color.setHSL.unit" => { let (h, s, l) = (r.s(), r.s(), r.s()); o.c(Color::default().set_hsl(h, s, l, r.cspace())) }
        "Color.copySRGBToLinear" => o.c(Color::default().copy_srgb_to_linear(&r.c())),
        "Color.copyLinearToSRGB" => o.c(Color::default().copy_linear_to_srgb(&r.c())),
        "Color.convertSRGBToLinear" => o.c(r.c().convert_srgb_to_linear()),
        "Color.convertLinearToSRGB" => o.c(r.c().convert_linear_to_srgb()),
        "Color.getHex" => { let c = r.c(); o.d(c.get_hex(r.cspace()) as f64) }
        "Color.getHexString" => { let c = r.c(); o.text = Some(c.get_hex_string(r.cspace())) }
        "Color.getHSL" => { let c = r.c(); let hsl = c.get_hsl(r.cspace()); o.a(&[hsl.h, hsl.s, hsl.l]) }
        "Color.getRGB" => { let c = r.c(); o.c(&c.get_rgb(r.cspace())) }
        "Color.getStyle" => { let c = r.c(); o.text = Some(c.get_style(r.cspace())) }
        "Color.offsetHSL" => { let mut c = r.c(); let (h, s, l) = (r.s(), r.s(), r.s()); o.c(c.offset_hsl(h, s, l)) }
        "Color.add" => { let mut a = r.c(); o.c(a.add(&r.c())) }
        "Color.addColors" => { let (a, b) = (r.c(), r.c()); o.c(Color::default().add_colors(&a, &b)) }
        "Color.addScalar" => { let mut a = r.c(); o.c(a.add_scalar(r.s())) }
        "Color.sub" => { let mut a = r.c(); o.c(a.sub(&r.c())) }
        "Color.multiply" => { let mut a = r.c(); o.c(a.multiply(&r.c())) }
        "Color.multiplyScalar" => { let mut a = r.c(); o.c(a.multiply_scalar(r.s())) }
        "Color.lerp" => { let mut a = r.c(); let b = r.c(); o.c(a.lerp(&b, r.s())) }
        "Color.lerpColors" => { let (a, b) = (r.c(), r.c()); o.c(Color::default().lerp_colors(&a, &b, r.s())) }
        "Color.lerpHSL" => { let mut a = r.c(); let b = r.c(); o.c(a.lerp_hsl(&b, r.s())) }
        "Color.setFromVector3" => o.c(Color::default().set_from_vector3(&r.v3())),
        "Color.applyMatrix3" => { let mut c = r.c(); o.c(c.apply_matrix3(&r.m3())) }
        "Color.equals" => { let a = r.c(); o.b(a.equals(&r.c())) }
        "Color.setStyle" => { let cs = r.cspace(); o.c(Color::new(0.25, 0.5, 0.75).set_style(r.text, cs)) }
        "Color.setColorName" => { let cs = r.cspace(); o.c(Color::new(0.25, 0.5, 0.75).set_color_name(r.text, cs)) }
        "Color.NAMES" => {
            let hex = Color::NAMES.iter().find(|(name, _)| *name == r.text).map(|(_, hex)| *hex);
            o.d(hex.map_or(f64::NAN, |h| h as f64))
        }

        // ---- ColorManagement
        "ColorManagement.SRGBToLinear" => o.s(color_management::srgb_to_linear(r.s())),
        "ColorManagement.LinearToSRGB" => o.s(color_management::linear_to_srgb(r.s())),
        "ColorManagement.convert" => { let mut c = r.c(); let (a, b) = (r.cspace(), r.cspace()); o.c(color_management::convert(&mut c, a, b)) }

        _ => return run_shapes(op, r, o),
    }

    true
}

fn matches(got: f64, expected: f64) -> bool {
    if expected.is_nan() || got.is_nan() {
        return expected.is_nan() && got.is_nan();
    }
    if expected.is_infinite() || got.is_infinite() {
        return got == expected;
    }
    (got - expected).abs() <= TOLERANCE * expected.abs().max(1.0)
}

fn check(name: &str) -> BTreeSet<String> {
    let fixture = load(name);
    let cases = fixture["cases"].as_array().unwrap();
    assert_eq!(fixture["meta"]["cases"].as_u64().unwrap() as usize, cases.len());

    let mut ops = BTreeSet::new();
    let mut failures = Vec::new();
    let (mut max_abs, mut max_scaled, mut values) = (0.0f64, 0.0f64, 0usize);
    // values that miss a plain absolute 1e-6, and the smallest |expected| among them (DECISIONS.md D2)
    let (mut over_absolute, mut smallest_over) = (0usize, f64::INFINITY);

    for (index, case) in cases.iter().enumerate() {
        let op = case["op"].as_str().unwrap();
        let input = numbers(&case["in"]);
        let expected = numbers(&case["out"]);
        ops.insert(op.to_string());

        let mut r = In { v: &input, i: 0, text: case.get("s").and_then(Value::as_str).unwrap_or("") };
        let mut o = Out::default();

        assert!(run(op, &mut r, &mut o), "{name}: no Rust dispatch for op {op}");
        assert_eq!(r.i, input.len(), "{name} case {index} ({op}): dispatcher read {} of {} inputs", r.i, input.len());
        assert_eq!(o.v.len(), expected.len(), "{name} case {index} ({op}): output length");

        let mut ok = o.v.iter().zip(&expected).all(|(g, e)| matches(*g, *e));
        if let Some(expected_text) = case.get("os").and_then(Value::as_str) {
            ok &= o.text.as_deref() == Some(expected_text);
        }

        for (g, e) in o.v.iter().zip(&expected) {
            if g.is_finite() && e.is_finite() {
                let err = (g - e).abs();
                max_abs = max_abs.max(err);
                max_scaled = max_scaled.max(err / e.abs().max(1.0));
                if err > TOLERANCE {
                    over_absolute += 1;
                    smallest_over = smallest_over.min(e.abs());
                }
            }
            values += 1;
        }

        if !ok && failures.len() < 12 {
            failures.push(format!(
                "case {index} {op}\n    in:       {input:?} {:?}\n    expected: {expected:?} {:?}\n    got:      {:?} {:?}",
                case.get("s"),
                case.get("os"),
                o.v,
                o.text
            ));
        }
    }

    let over = if over_absolute == 0 { String::new() } else { format!("  ({over_absolute} values over absolute 1e-6, all with |exp| >= {smallest_over:.1})") };
    println!(
        "parity {name:<16} {:>5} cases {:>3} ops {values:>6} values  max |err|/max(1,|exp|) {max_scaled:.3e}  max |err| {max_abs:.3e}{over}",
        cases.len(),
        ops.len()
    );

    assert!(failures.is_empty(), "{name}: parity failures (first {}):\n{}", failures.len(), failures.join("\n"));
    ops
}

macro_rules! parity_tests {
    ($($test:ident => $file:literal),+ $(,)?) => {
        $(
            #[test]
            fn $test() {
                check($file);
            }
        )+

        const FILES: &[&str] = &[$($file),+];
    };
}

parity_tests! {
    math_utils_ => "MathUtils",
    vector2 => "Vector2",
    vector3 => "Vector3",
    vector4 => "Vector4",
    matrix3 => "Matrix3",
    matrix4 => "Matrix4",
    quaternion => "Quaternion",
    euler => "Euler",
    color => "Color",
    color_management_ => "ColorManagement",
    box3 => "Box3",
    sphere => "Sphere",
    plane => "Plane",
    ray => "Ray",
    frustum => "Frustum",
    triangle => "Triangle",
    line3 => "Line3",
    spherical => "Spherical",
    cylindrical => "Cylindrical",
}

#[test]
fn every_generated_op_is_checked() {
    let path = format!("{}/ops.json", fixture_dir());
    let listed: BTreeSet<String> = serde_json::from_str::<Vec<String>>(&std::fs::read_to_string(path).unwrap()).unwrap().into_iter().collect();

    let mut seen = BTreeSet::new();
    for file in FILES {
        for case in load(file)["cases"].as_array().unwrap() {
            seen.insert(case["op"].as_str().unwrap().to_string());
        }
    }

    assert_eq!(seen, listed, "ops.json and the fixture files disagree");

    let types: BTreeSet<&str> = listed.iter().map(|op| op.split_once('.').unwrap().0).collect();
    assert_eq!(types, FILES.iter().copied().collect(), "a fixture type has no parity test");
}
